import{_ as n,o as s,c as o,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0074 — Adresse d'un compte fédéré : retenue si le fournisseur la dit vérifiée ou si l'organisation lui fait confiance","description":"Extrait de docs/adr/0074-adresse-oidc-retenue-si-verifiee-ou-de-confiance.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0074 — Adresse d'un compte fédéré : retenue si le fournisseur la dit vérifiée ou si l'organisation lui fait confiance","description":"Extrait de docs/adr/0074-adresse-oidc-retenue-si-verifiee-ou-de-confiance.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0074-adresse-oidc-retenue-si-verifiee-ou-de-confiance.md","filePath":"developpeurs/adr/0074-adresse-oidc-retenue-si-verifiee-ou-de-confiance.md"}`),t={name:"developpeurs/adr/0074-adresse-oidc-retenue-si-verifiee-ou-de-confiance.md"};function a(i,e,d,c,u,l){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0074--adresse-dun-compte-fédéré--retenue-si-le-fournisseur-la-dit-vérifiée-ou-si-lorganisation-lui-fait-confiance" tabindex="-1">ADR-0074 — Adresse d&#39;un compte fédéré : retenue si le fournisseur la dit vérifiée ou si l&#39;organisation lui fait confiance <a class="header-anchor" href="#adr-0074--adresse-dun-compte-fédéré--retenue-si-le-fournisseur-la-dit-vérifiée-ou-si-lorganisation-lui-fait-confiance" aria-label="Permalink to &quot;ADR-0074 — Adresse d&#39;un compte fédéré : retenue si le fournisseur la dit vérifiée ou si l&#39;organisation lui fait confiance {#adr-0074--adresse-dun-compte-fédéré--retenue-si-le-fournisseur-la-dit-vérifiée-ou-si-lorganisation-lui-fait-confiance}&quot;">​</a></h1><p><strong>Date :</strong> 21 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 21 octobre 2026, constat SEC-8 (« L&#39;adresse OIDC non vérifiée est traitée comme une preuve ») ; issue #37 (lot 1) ; arbitrage du Product Owner du 21/10/2026 (option b : un réglage par fournisseur, sur le modèle de l&#39;option « Trust Email » de Keycloak) ; CDC_CMS_AI_Native_v1.1 §8.1 (compte usager, OIDC type FranceConnect), §8.3 (RGPD du compte) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0040-echangeur-oidc-des-usagers-livre-inactif">ADR-0040</a> — la création du compte fédéré : le compte reste « confirmé d&#39;office » (la fédération prouve la connexion), mais l&#39;adresse transmise n&#39;est plus rangée sans condition. Complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0059-droits-des-abonnes">ADR-0059</a> dont le rattachement par l&#39;adresse suppose que celle-ci a été prouvée.</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>À la première connexion par un fournisseur OIDC, <code>complete_oidc_login</code> (<code>app/end_users/oidc.py</code>) créait le compte avec <code>email=claims.get(&quot;email&quot;)</code> et <code>confirmed_at=now</code>. La revendication <code>email_verified</code> n&#39;était lue nulle part.</p><p>Or <code>account_email_key</code> (<code>app/end_users/subscribers.py</code>) fait confiance à toute adresse d&#39;un compte <strong>confirmé</strong> : l&#39;export du compte (<code>app/end_users/export.py</code>) et son effacement atteignent les fiches d&#39;abonnement à la lettre d&#39;information de cette adresse (ADR-0059). Si le fournisseur transmet une adresse qu&#39;il n&#39;a pas vérifiée — une adresse saisie par la personne, ou choisie par un tiers —, le compte fédéré exporte puis <strong>efface les abonnements de quelqu&#39;un d&#39;autre</strong>.</p><p>Une seconde défaillance, sans rapport avec la confiance : une adresse déjà portée par un autre compte de l&#39;organisation faisait échouer le <code>flush()</code> sur <code>uq_end_users_organization_email</code> — une réponse 500, à la première connexion d&#39;une personne dont l&#39;adresse figure déjà dans l&#39;extranet.</p><p>Le risque dépend de ce que le fournisseur met dans <code>email</code>, que le Core ne maîtrise pas : FranceConnect, un annuaire de collectivité ou un fournisseur grand public n&#39;offrent pas les mêmes garanties.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Un réglage par fournisseur : <code>trust_email</code>, « Adresse de confiance », faux par défaut.</strong></p><ul><li>Champ booléen de <code>OidcClientSettings</code> (et donc de <code>OidcClientSettingsWrite</code>), rangé avec les autres réglages du fournisseur dans <code>organizations.settings</code> (JSONB) : <strong>aucune migration</strong>. Une politique écrite avant cette ADR n&#39;a pas le champ et se relit à faux.</li><li>Sur le modèle de l&#39;option « Trust Email » de Keycloak : l&#39;organisation déclare que ce fournisseur vérifie lui-même les adresses qu&#39;il transmet. C&#39;est une décision de l&#39;exploitant, prise fournisseur par fournisseur.</li></ul><p><strong>2. À la création du compte fédéré, l&#39;adresse n&#39;est retenue que si elle est vérifiée ou de confiance.</strong></p><ul><li>Retenue si la revendication <code>email_verified</code> vaut vrai — le booléen <code>True</code>, ou la chaîne <code>&quot;true&quot;</code> sans égard à la casse, que certains fournisseurs envoient à la place du booléen — <strong>ou</strong> si le fournisseur est déclaré « adresse de confiance ». Sinon (revendication absente, fausse ou illisible, fournisseur non déclaré de confiance), le compte est créé <strong>sans adresse</strong> (<code>email = NULL</code>).</li><li><code>confirmed_at = now</code> reste posé : la fédération prouve la connexion, pas l&#39;adresse. Sans adresse, <code>account_email_key</code> rend <code>None</code> et l&#39;export comme l&#39;effacement du compte n&#39;atteignent aucune fiche d&#39;abonnement.</li><li>L&#39;adresse retenue est normalisée comme celle des abonnements (<code>normalize_email</code>). Une valeur qui n&#39;est pas une chaîne, qui n&#39;a pas d&#39;arobase ou qui dépasse la colonne (255 caractères) est ignorée : le fournisseur ne fait pas échouer la connexion pour un champ facultatif.</li><li><strong>Une connexion ultérieure ne réécrit jamais l&#39;adresse.</strong> Le code de la branche « identité déjà liée » ne la touche pas, et un test le fixe : une adresse non retenue ne remplace pas une adresse existante, et une adresse vérifiée ne la remplace pas non plus (changer d&#39;adresse passe par le compte, pas par la fédération).</li></ul><p><strong>3. Une adresse déjà portée par un autre compte de l&#39;organisation : repli sans adresse, jamais de rattachement.</strong></p><ul><li>Le Core vérifie l&#39;existence par une requête <strong>avant</strong> le <code>flush</code>, sur l&#39;organisation puis l&#39;adresse, <strong>sans égard à la casse</strong> (les abonnements normalisent en minuscules : deux comptes qui ne diffèrent que par la casse ont la même clé d&#39;abonnement). Si un compte la porte, le compte fédéré est créé <strong>sans adresse</strong> et la connexion réussit normalement.</li><li><strong>Pas de rattachement automatique</strong> au compte existant : quiconque obtiendrait une adresse chez un fournisseur laxiste hériterait du compte local (et de ses demandes, de son espace personnel). C&#39;est une prise de compte.</li><li><strong>Pas d&#39;oracle.</strong> La réponse est celle d&#39;une adresse non vérifiée : même forme, même statut, aucune adresse dans le compte. La personne ne peut pas distinguer « adresse non vérifiée » de « adresse déjà prise ». Le seul témoin est une ligne du journal technique <code>teuthis.oidc</code>, <code>oidc_adresse_deja_portee</code>, qui porte la clé du fournisseur et un indicateur de course, <strong>ni l&#39;adresse, ni le <code>sub</code></strong>. Le journal d&#39;accès aux données personnelles reçoit seulement le fait « le compte porte une adresse ou non » (<code>adresse_rangee</code>), jamais la valeur.</li><li><strong>Course résiduelle.</strong> Entre la requête et l&#39;insertion, une inscription locale peut prendre l&#39;adresse. L&#39;insertion se fait dans un point de sauvegarde ; une <code>IntegrityError</code> est rattrapée et l&#39;insertion est <strong>rejouée sans adresse</strong> (le repli normal). Si le rejeu échoue aussi, la cause n&#39;est plus l&#39;adresse mais le login (dérivé du <code>sub</code>) : une connexion parallèle du même usager vient d&#39;ouvrir son compte, il n&#39;y a rien à replier et le Core lève <code>OidcError</code> (400, « recommencer la connexion ») plutôt qu&#39;un 500. Choisi plutôt qu&#39;un simple <code>OidcError</code> d&#39;emblée : la course sur l&#39;adresse est bénigne et se résout sans renvoyer la personne à l&#39;écran de connexion ; le message d&#39;erreur ne contient aucune donnée.</li></ul><p><strong>4. Back-office.</strong> Extranet › Politique, sur la déclaration de chaque fournisseur : une case « Adresse de confiance », décochée par défaut, avec un texte d&#39;aide lié par <code>aria-describedby</code> qui dit le risque (cochée à tort, une adresse inexacte rattache le compte aux abonnements d&#39;une autre personne). Le BFF relaie la politique telle quelle ; le type <code>OidcClientSettings</code> de l&#39;admin gagne <code>trust_email</code>.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>(a) <code>email_verified</code> seul</strong>, sans réglage</td><td>Un fournisseur qui n&#39;envoie pas la revendication (annuaire de collectivité, fournisseur simple) n&#39;aurait jamais d&#39;adresse sur ses comptes, même quand l&#39;organisation sait qu&#39;il vérifie ses adresses. Le réglage par fournisseur est le seul endroit où cette connaissance peut s&#39;exprimer.</td></tr><tr><td><strong>Rattacher le compte fédéré au compte local portant la même adresse</strong></td><td>Prise de compte : l&#39;adresse vient d&#39;un fournisseur que le Core ne maîtrise pas, le compte local appartient à quelqu&#39;un. Même avec <code>email_verified</code>, la vérification est celle du fournisseur, pas celle de l&#39;organisation. Un rattachement légitime passe par une preuve que le Core organise lui-même (jeton envoyé à l&#39;adresse), hors de cette ADR.</td></tr><tr><td><strong>Refuser la connexion quand l&#39;adresse est déjà prise</strong> (<code>OidcError</code>)</td><td>Oracle : la personne apprendrait qu&#39;un compte local existe sous cette adresse, et la connexion fédérée — qui n&#39;a rien de fautif — échouerait pour une raison que l&#39;usager ne peut pas corriger.</td></tr><tr><td><strong>Ne plus poser <code>confirmed_at</code> pour un compte fédéré</strong> (recommandation de l&#39;audit)</td><td>Le compte fédéré n&#39;a pas de mot de passe ni de jeton à confirmer : le laisser « non confirmé » le soumettrait à la purge des inscriptions non confirmées (24 h par défaut) alors que la personne s&#39;est bien connectée. La confirmation du compte et la preuve de l&#39;adresse sont deux choses ; la seconde est portée par la présence de l&#39;adresse.</td></tr><tr><td><strong>Rattacher par jeton de confirmation envoyé à l&#39;adresse</strong> (autre recommandation de l&#39;audit)</td><td>Utile, mais c&#39;est un parcours à construire (courriel, jeton, écran de retour) pour un besoin que l&#39;option retenue couvre sans lui : sans adresse, rien n&#39;est rattaché. Laissé en action ouverte si un site veut proposer d&#39;ajouter une adresse à son compte.</td></tr><tr><td><strong>Une migration qui ajoute <code>email_verified</code> à <code>end_users</code></strong></td><td>Aucune des décisions n&#39;en a besoin : la preuve est portée par la présence de l&#39;adresse, et les réglages du fournisseur sont en JSON.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un compte fédéré n&#39;atteint plus les abonnements d&#39;une adresse non prouvée : l&#39;export et l&#39;effacement ne touchent que ce que la personne a prouvé.</li><li>La première connexion d&#39;une personne dont l&#39;adresse existe déjà dans l&#39;extranet ne fait plus de 500, et ne donne aucune prise de compte.</li><li>L&#39;exploitant garde la main : un fournisseur qu&#39;il sait fiable se déclare « de confiance » sans code.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Un compte fédéré n&#39;a plus d&#39;adresse par défaut</strong> : les courriels qui s&#39;adressent au compte (relances d&#39;inactivité du cycle de vie, notifications) n&#39;ont pas de destinataire tant que le fournisseur ne vérifie pas l&#39;adresse ou que l&#39;organisation ne le déclare pas de confiance. Le cycle de vie s&#39;applique toujours : un compte sans adresse n&#39;est pas relancé, mais il est supprimé le moment venu (<code>app/end_users/lifecycle.py</code>). À mesurer à la mise en production d&#39;une connexion fédérée.</li><li><strong>Les comptes fédérés déjà créés gardent l&#39;adresse qu&#39;ils ont reçue</strong>, sans que rien ne dise si elle était vérifiée : l&#39;identité pivot ne range que les revendications déclarées par l&#39;organisation (<code>pivot_claims</code>, qui ne contient pas <code>email</code> par défaut), et <code>email_verified</code> n&#39;a jamais été conservée. Voir l&#39;action ouverte.</li><li><strong>Une connexion ultérieure n&#39;ajoute pas d&#39;adresse</strong> à un compte créé sans elle, même si le fournisseur la dit vérifiée cette fois. C&#39;est volontaire dans ce lot (jamais de réécriture) ; ajouter l&#39;adresse à une connexion suivante serait un complément à décider.</li><li>Un fournisseur déclaré « de confiance » qui enverrait explicitement <code>email_verified: false</code> voit son adresse retenue : la déclaration de l&#39;organisation prime sur la revendication. C&#39;est la sémantique de l&#39;option de Keycloak, et c&#39;est dit dans l&#39;aide de la case.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Réglage <code>trust_email</code> (faux par défaut, aucune migration), règle de rétention de l&#39;adresse à la création du compte fédéré (<code>email_verified</code> booléen ou chaîne <code>&quot;true&quot;</code>, ou fournisseur de confiance), repli sans adresse quand l&#39;adresse est déjà portée (requête préalable sans égard à la casse, <code>IntegrityError</code> rattrapée dans un point de sauvegarde, <code>OidcError</code> si le repli est impossible), connexions ultérieures sans réécriture. — <code>apps/api/app/end_users/policy.py</code> (<code>OidcClientSettings.trust_email</code>), <code>apps/api/app/end_users/oidc.py</code> (<code>verified_email_of</code>, <code>_email_is_taken</code>, <code>complete_oidc_login</code>). Preuves : <code>apps/api/tests/test_oidc_adresse_de_confiance.py</code> (<strong>rouge avant</strong> : 21 tests sur 36 échouent avec le code d&#39;origine, dont les cas de collision, qui lèvent la violation d&#39;unicité non gérée, un 500 ; vert ensuite) ; export et effacement du compte sans adresse n&#39;atteignent pas la fiche de lettre d&#39;information de cette adresse ; <code>test_oidc_exchanger.py</code>, <code>test_end_users.py</code>, <code>test_abonnements_du_compte.py</code> et <code>test_droits_des_abonnes.py</code> inchangés et verts.</li><li>[x] Admin : case « Adresse de confiance » avec son aide liée par <code>aria-describedby</code>, type <code>trust_email</code> partagé. — <code>apps/admin/pages/extranet/politique.vue</code>, <code>apps/admin/types/api.ts</code>. Preuves : <code>lint</code>, <code>typecheck</code> et <code>build</code> de l&#39;admin verts le 21/10/2026 ; recette dans un navigateur non faite.</li><li>[x] Notice d&#39;exploitation : le réglage, la règle et le repli sur collision. — <code>docs/notice-utilisateur.md</code>, §6.7.</li><li>[ ] <strong>Traiter les comptes fédérés déjà créés avec une adresse non vérifiée.</strong> Ils se reconnaissent sans migration : une <code>end_user_federated_identities</code> existe pour eux, <code>password_hash</code> est nul et <code>email</code> est renseignée. Rien ne dit si l&#39;adresse était vérifiée (voir Conséquences). Proposition, à décider : pour chaque organisation dont aucun fournisseur n&#39;est déclaré « de confiance », vider l&#39;adresse de ces comptes par un script d&#39;exploitation à lancer une fois (<code>UPDATE end_users SET email = NULL</code> limité aux comptes fédérés, journalisé), après avoir listé les comptes concernés (<code>dry_run</code>) ; pour une organisation dont le fournisseur est de confiance, ne rien faire. Un compte dont l&#39;adresse a été vidée reste utilisable, les abonnements de l&#39;adresse cessent d&#39;être rattachés à lui.</li><li>[ ] <strong>Établir ce que FranceConnect rend réellement dans <code>email</code> et <code>email_verified</code></strong>, sur l&#39;intégration réelle (<code>fcp-low.integ01.dev-franceconnect.fr</code>), avant de recommander ou non de cocher « Adresse de confiance » pour ce fournisseur. Le dépôt ne le dit pas et cette ADR ne l&#39;affirme pas ; la recette n&#39;a exercé qu&#39;un fournisseur simulé (action ouverte de l&#39;ADR-0040).</li><li>[ ] <strong>Instruire le même défaut pour le numéro de téléphone</strong> : <code>account_phone_keys</code> rattache au compte les alertes SMS d&#39;un numéro lu dans l&#39;identité pivot (<code>phone_number</code>, si l&#39;organisation l&#39;a déclaré dans <code>pivot_claims</code>), sans que <code>phone_number_verified</code> soit lue. Même famille que SEC-8, hors du périmètre de cette ADR.</li></ul>',24)])])}const f=n(t,[["render",a]]);export{m as __pageData,f as default};
